source=root/'scripts/standalone-sdk-boundary-probe.c';names=['chdir','setvbuf','__fbufsize','__fpending','sdk_standard','sdk_errno','sdk_constant','sdk_fcntl','sdk_assert','sdk_now','access','getcwd','setuid','setgid','sleep','wait','malloc','free','fopen','freopen','fclose','fflush','fileno','fread','fwrite','fgetc','fputc','ungetc','fseek','ftell','feof','ferror','clearerr','__errno_location','open','close','dup','dup2','lseek','read','write']
